    "adda7f9f": {"text":"défenseur","hash":"h1-d2646fea"},
    "ae09e19e": {"text":"Mods groupés","hash":"h1-e7456a98"},
    "ae0ae28c": {"text":"Gloire ou fossé – la bière décide.","hash":"h1-d4c6f0ca"},
    "ae23c411": {"text":"De la chaleur, de la paille et une porte grillagée.","hash":"h1-57f30e93"},
    "ae2ab5a2": {"text":"🗺 {mode} — votre meilleure revendication : {name}, {held} (besoin de {need})","hash":"h1-81630b36"},
